import { saveAgentArtifact, listAgentArtifacts, type AgentArtifact } from "../agent-store";

export type FreeEngagement = {
  id: string;
  name: string;
  client: string;
  type: string;
  status: string;
  startDate: string;
  endDate: string;
  teamLead: string;
  scope: string;
  outOfScope?: string;
  objectives?: string;
  execSummary?: string;
  findings: unknown[];
  storageSource: "free";
};

export async function saveRedTeamEngagement(eng: FreeEngagement): Promise<AgentArtifact<FreeEngagement>> {
  return saveAgentArtifact({
    agent: "redteam",
    kind: "engagement",
    title: eng.name,
    id: eng.id,
    data: eng,
  });
}

export async function loadRedTeamEngagements(): Promise<AgentArtifact<FreeEngagement>[]> {
  return listAgentArtifacts<FreeEngagement>("redteam");
}
