import type { PentestReport } from "@/lib/redteam/pentest-types";
import { loadPentestReports } from "./pentest";
import { loadRedTeamEngagements, saveRedTeamEngagement, type FreeEngagement } from "./redteam";

/** Minimal portal engagement — RedTeamPortal maps this via recount(). */
export type PortalEngagementInput = {
  id: string;
  name: string;
  client: string;
  type: string;
  status: string;
  startDate: string;
  endDate: string;
  scope: string;
  outOfScope: string;
  teamLead: string;
  operators: string[];
  objectives: string[];
  rules: string[];
  findings: PortalFinding[];
  executiveSummary: string;
  methodology: string;
  storageSource: "free" | "supabase";
};

export type PortalFinding = {
  id: string;
  engagementId: string;
  title: string;
  severity: string;
  status: string;
  affectedSystem: string;
  description: string;
  evidence: string;
  recommendation: string;
  mitreTactic: string;
  mitreTechnique: string;
  discoveredAt: string;
  remediatedAt: string | null;
  verifiedBy: string | null;
};

function mapPentestReport(report: PentestReport, artifactId: string): PortalEngagementInput {
  return {
    id: artifactId,
    name: `Auto Pentest — ${report.hostname}`,
    client: report.hostname,
    type: "Automated Web Pentest",
    status: "reporting",
    startDate: report.scannedAt.slice(0, 10),
    endDate: report.scannedAt.slice(0, 10),
    teamLead: "Pentest Agent",
    scope: report.target,
    outOfScope: "",
    operators: [],
    objectives: [report.methodology],
    rules: [],
    executiveSummary: report.executiveSummary,
    methodology: report.methodology,
    storageSource: "free",
    findings: report.findings.map((f) => ({
      id: f.id,
      engagementId: artifactId,
      title: f.title,
      severity: f.severity === "info" ? "informational" : f.severity,
      status: "open",
      affectedSystem: f.affectedAsset,
      description: f.description,
      evidence: f.evidence,
      recommendation: f.recommendation,
      mitreTactic: f.mitreTactic ?? "",
      mitreTechnique: f.mitreTechnique ?? "",
      discoveredAt: report.scannedAt,
      remediatedAt: null,
      verifiedBy: null,
    })),
  };
}

function mapFreeEngagement(eng: FreeEngagement): PortalEngagementInput {
  return {
    id: eng.id,
    name: eng.name,
    client: eng.client,
    type: eng.type,
    status: eng.status,
    startDate: eng.startDate,
    endDate: eng.endDate,
    teamLead: eng.teamLead,
    scope: eng.scope,
    outOfScope: eng.outOfScope ?? "",
    operators: [],
    objectives: eng.objectives ? [eng.objectives] : [],
    rules: [],
    executiveSummary: eng.execSummary ?? "",
    methodology: "PTES",
    storageSource: "free",
    findings: (eng.findings as PortalFinding[]) ?? [],
  };
}

export async function loadFreePortalEngagements(): Promise<PortalEngagementInput[]> {
  const [pentestArts, redteamArts] = await Promise.all([
    loadPentestReports(),
    loadRedTeamEngagements(),
  ]);

  const pentestIds = new Set(pentestArts.map((a) => a.id));
  const manual = redteamArts.filter((a) => !pentestIds.has(a.id));

  return [
    ...pentestArts.map((a) => mapPentestReport(a.data, a.id)),
    ...manual.map((a) => mapFreeEngagement(a.data)),
  ];
}

export async function createFreePortalEngagement(input: {
  name: string;
  client: string;
  type: string;
  startDate: string;
  endDate: string;
  teamLead: string;
  scope: string;
}): Promise<PortalEngagementInput> {
  const eng: FreeEngagement = {
    id: crypto.randomUUID?.() ?? `eng-${Date.now()}`,
    name: input.name,
    client: input.client,
    type: input.type,
    status: "planning",
    startDate: input.startDate,
    endDate: input.endDate,
    teamLead: input.teamLead,
    scope: input.scope,
    findings: [],
    storageSource: "free",
  };
  await saveRedTeamEngagement(eng);
  return mapFreeEngagement(eng);
}

export async function updateFreeFindingStatus(
  engagementId: string,
  findingId: string,
  newStatus: string,
): Promise<void> {
  const arts = await loadRedTeamEngagements();
  const art = arts.find((a) => a.id === engagementId);
  if (!art) return;
  const findings = (art.data.findings as PortalFinding[]).map((f) =>
    f.id === findingId
      ? {
          ...f,
          status: newStatus,
          remediatedAt: newStatus === "fixed" ? new Date().toISOString().slice(0, 10) : f.remediatedAt,
        }
      : f,
  );
  await saveRedTeamEngagement({ ...art.data, findings });
}
